public class InnerDataAutomationProjectStandardOutputConfigurationFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration>
{

    internal InnerDataAutomationProjectVideoStandardOutputConfigurationFactory VideoFactory { get; set; }

    internal InnerDataAutomationProjectDocumentStandardOutputConfigurationFactory DocumentFactory { get; set; }

    internal InnerDataAutomationProjectImageStandardOutputConfigurationFactory ImageFactory { get; set; }

    internal InnerDataAutomationProjectAudioStandardOutputConfigurationFactory AudioFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration Create()
    {
        var standardOutputConfigurationResult = CreateStandardOutputConfiguration();
        factoryAction?.Invoke(standardOutputConfigurationResult);

        return standardOutputConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration CreateStandardOutputConfiguration()
    {
        var standardOutputConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration();

        return standardOutputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.StandardOutputConfiguration result)
    {
        base.CreateChildren(result);

        result.Video ??= VideoFactory?.Build();
        result.Document ??= DocumentFactory?.Build();
        result.Image ??= ImageFactory?.Build();
        result.Audio ??= AudioFactory?.Build();
    }

} // End Of Class

